BEGIN;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS tenant_id text;
UPDATE projects SET tenant_id=COALESCE(NULLIF(tenant_id,''),NULLIF(metadata->>'tenantId',''),created_by) WHERE tenant_id IS NULL OR tenant_id='';
ALTER TABLE projects ALTER COLUMN tenant_id SET NOT NULL;
CREATE INDEX IF NOT EXISTS projects_tenant_updated_idx ON projects(tenant_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS forge_workflow_templates (id text PRIMARY KEY,tenant_id text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',active_version_id text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','INACTIVE')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS forge_workflow_templates_tenant_name_uq ON forge_workflow_templates(tenant_id,name);
CREATE INDEX IF NOT EXISTS forge_workflow_templates_tenant_status_idx ON forge_workflow_templates(tenant_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS forge_workflow_template_versions (id text PRIMARY KEY,template_id text NOT NULL REFERENCES forge_workflow_templates(id) ON DELETE RESTRICT,tenant_id text NOT NULL,version integer NOT NULL CHECK(version>0),definition jsonb NOT NULL,content_hash char(64) NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','INACTIVE')),release_epoch bigint NOT NULL DEFAULT 0,created_by text NOT NULL,activated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(template_id,version),UNIQUE(template_id,content_hash));
CREATE INDEX IF NOT EXISTS forge_workflow_template_versions_tenant_idx ON forge_workflow_template_versions(tenant_id,template_id,version DESC);
CREATE UNIQUE INDEX IF NOT EXISTS forge_workflow_template_versions_active_uq ON forge_workflow_template_versions(template_id) WHERE status='ACTIVE';
ALTER TABLE forge_workflow_templates ADD CONSTRAINT forge_workflow_templates_active_fk FOREIGN KEY(active_version_id) REFERENCES forge_workflow_template_versions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE IF NOT EXISTS forge_workflow_template_events (id bigserial PRIMARY KEY,template_version_id text NOT NULL REFERENCES forge_workflow_template_versions(id) ON DELETE RESTRICT,tenant_id text NOT NULL,actor text NOT NULL,event_type text NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_workflow_template_events_lookup_idx ON forge_workflow_template_events(tenant_id,template_version_id,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_execution_plans (id text PRIMARY KEY,tenant_id text NOT NULL,project_id text NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,episode_id text NOT NULL REFERENCES episodes(id) ON DELETE RESTRICT,template_version_id text NOT NULL REFERENCES forge_workflow_template_versions(id) ON DELETE RESTRICT,template_content_hash char(64) NOT NULL,release_epoch bigint NOT NULL,snapshot jsonb NOT NULL,content_hash char(64) NOT NULL,status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS forge_execution_plans_episode_active_uq ON forge_execution_plans(episode_id) WHERE status IN ('QUEUED','RUNNING');
CREATE INDEX IF NOT EXISTS forge_execution_plans_tenant_episode_idx ON forge_execution_plans(tenant_id,episode_id,created_at DESC);
CREATE INDEX IF NOT EXISTS forge_execution_plans_template_idx ON forge_execution_plans(template_version_id,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_execution_plan_stages (id text PRIMARY KEY,plan_id text NOT NULL REFERENCES forge_execution_plans(id) ON DELETE CASCADE,stage_id text NOT NULL,runtime_stage text NOT NULL,depends_on jsonb NOT NULL DEFAULT '[]'::jsonb,input_contract jsonb NOT NULL DEFAULT '{}'::jsonb,output_contract jsonb NOT NULL DEFAULT '{}'::jsonb,retry_policy jsonb NOT NULL DEFAULT '{}'::jsonb,timeout_seconds integer NOT NULL,resource_class text NOT NULL DEFAULT 'default',approval_requirement text,feature_flag text,job_id text,status text NOT NULL DEFAULT 'BLOCKED' CHECK(status IN ('BLOCKED','QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')),output_version_ids jsonb NOT NULL DEFAULT '[]'::jsonb,output_artifact_ids jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,stage_id));
CREATE INDEX IF NOT EXISTS forge_execution_plan_stages_ready_idx ON forge_execution_plan_stages(plan_id,status);
CREATE TABLE IF NOT EXISTS forge_job_dependencies (job_id text NOT NULL REFERENCES forge_jobs(id) ON DELETE CASCADE,depends_on_job_id text NOT NULL REFERENCES forge_jobs(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_id,depends_on_job_id),CHECK(job_id<>depends_on_job_id));
CREATE INDEX IF NOT EXISTS forge_job_dependencies_reverse_idx ON forge_job_dependencies(depends_on_job_id);
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS execution_plan_id text REFERENCES forge_execution_plans(id) ON DELETE SET NULL;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS plan_stage_id text;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS template_version_id text REFERENCES forge_workflow_template_versions(id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS forge_jobs_execution_plan_idx ON forge_jobs(execution_plan_id,status,created_at);
COMMIT;